; steady.asm -- chapter 32: bars counted from the interrupt
; generated by gen32.py
        INCLUDE "msx.inc"
        OUTPUT "steady.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
count   EQU VARS                ; the frames left
wait    EQU VARS + 1            ; the turns of 30 T-states to the first bar
crowd   EQU VARS + 3            ; crowd.asm: its sprites' line, less 1
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; steady.asm: poll.asm's bars, from the handler of the frame's interrupt, in
; mode 2: the CPU halts before it comes, and answers it within a step of HALT.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; the backdrop white
        VRAM_WRITE $0000        ; the patterns: none first
        xor a
        ld e, 16
        call fill
        VRAM_WRITE $0100        ; the set of chapter 30 at code 32
        ld hl, font
        ld e, 3
        call send
        VRAM_WRITE $2000        ; black ink on transparent paper
        ld a, $10
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $3800        ; sprite patterns: a block and a ball
        ld hl, shapes
        ld b, 16
        otir
        VRAM_WRITE $1B00        ; the sprites
        ld hl, attributes
        ld b, 1
        otir
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 897              ; 60 Hz ...
        jr nc, .sixty
        ld hl, 1284             ; ... and 50 Hz
.sixty: ld (wait), hl
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; the display on, and the frame's signal
        in a, (VDP_CTRL)
        ld a, 16
        ld (count), a
        ei
main:   halt                    ; the handler runs, and comes back here
        ld a, (count)
        or a
        jr nz, main
        di
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret

; send: E blocks of 256 bytes from HL with OTIR, the display off (chapter 31)
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret

; fill: E blocks of 256 bytes of A, the display off
fill:   ld b, 0
.out:   out (VDP_DATA), a
        djnz .out
        dec e
        jr nz, .out
        ret

; isr: every frame. A wait from the signal to line 48 of the paper, and the bars
isr:    in a, (VDP_CTRL)        ; the status: the signal down
        ld bc, (wait)
.t:     dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .t               ; 13: 30 T-states a turn
        ld a, 7                 ; cyan
        out (VDP_CTRL), a
        ld a, $87
b0:     out (VDP_CTRL), a       ; R#7: the bar from line 48
        ld bc, 58               ; 1,784 T-states in all
.w0:    dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .w0              ; 13
        ld a, (hl)              ;  8
        DUP 6                   ; 6 x 5
        nop
        EDUP
        ld a, 15                ; white
        out (VDP_CTRL), a
        ld a, $87
e0:     out (VDP_CTRL), a       ; R#7: white again
        ld bc, 301              ; 9,080 T-states in all
.w1:    dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .w1              ; 13
        DUP 3                   ; 3 x 8
        ld a, (hl)
        EDUP
        DUP 4                   ; 4 x 5
        nop
        EDUP
        ld a, 7                 ; cyan
        out (VDP_CTRL), a
        ld a, $87
b1:     out (VDP_CTRL), a       ; R#7: the bar from line 96
        ld bc, 58               ; 1,784 T-states in all
.w2:    dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .w2              ; 13
        ld a, (hl)              ;  8
        DUP 6                   ; 6 x 5
        nop
        EDUP
        ld a, 15                ; white
        out (VDP_CTRL), a
        ld a, $87
e1:     out (VDP_CTRL), a       ; R#7: white again
        ld bc, 301              ; 9,080 T-states in all
.w3:    dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .w3              ; 13
        DUP 3                   ; 3 x 8
        ld a, (hl)
        EDUP
        DUP 4                   ; 4 x 5
        nop
        EDUP
        ld a, 7                 ; cyan
        out (VDP_CTRL), a
        ld a, $87
b2:     out (VDP_CTRL), a       ; R#7: the bar from line 144
        ld bc, 58               ; 1,784 T-states in all
.w4:    dec bc                  ;  7
        ld a, b                 ;  5
        or c                    ;  5
        jr nz, .w4              ; 13
        ld a, (hl)              ;  8
        DUP 6                   ; 6 x 5
        nop
        EDUP
        ld a, 15                ; white
        out (VDP_CTRL), a
        ld a, $87
e2:     out (VDP_CTRL), a       ; R#7: white again
        ld hl, count
        dec (hl)
        ei
        ret
